import json
import subprocess
import sys
import time
from pathlib import Path
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('warehouse-inventory')
SCRIPT = Path('/opt/warehouse/scripts/reconcile_counts.py')
RUN_LOG = Path('/var/lib/warehouse/reconcile_runs.jsonl')


def _record_run(zone: str, count_file: Path, returncode: int) -> None:
    RUN_LOG.parent.mkdir(parents=True, exist_ok=True)
    entry = {'ts': int(time.time()), 'zone': zone, 'counts': str(count_file), 'code': returncode}
    with RUN_LOG.open('a') as f:
        f.write(json.dumps(entry) + '\n')


@mcp.tool()
def run_cycle_count_reconciliation(zone: str, count_file: str, timeout_s: int=300) -> dict:
    p = Path(count_file)
    if not p.is_file():
        return {'ok': False, 'error': f'count file not found: {count_file}'}
    if not zone.isalnum():
        return {'ok': False, 'error': 'invalid zone code'}
    cmd = [sys.executable, '-I', str(SCRIPT), '--zone', zone, '--counts', str(p)]
    try:
        r = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout_s)
    except subprocess.TimeoutExpired:
        return {'ok': False, 'error': f'timed out after {timeout_s}s'}
    _record_run(zone, p, r.returncode)
    out = r.stdout.strip().splitlines()
    err = r.stderr.strip().splitlines()
    return {'ok': r.returncode == 0, 'code': r.returncode, 'stdout': out[-50:], 'stderr': err[-20:]}
